// 07 · Assemble the invoice from the stored order lines, and recompute the
// money from scratch. WF1 already validated these numbers - we verify anyway,
// because the sheet is editable by humans between the two workflows.
const cfg   = $('02 · Config').first().json;
const order = $('05 · One at a time').first().json;

const round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;

const lines = $input.all()
  .map((i) => i.json)
  .filter((l) => String(l.order_id) === String(order.order_id))
  .sort((a, b) => Number(a.line_no) - Number(b.line_no))
  .map((l) => {
    const qty  = Number(l.qty) || 0;
    const unit = round2(l.unit_price_excl_vat);
    return {
      line_no:     Number(l.line_no),
      sku:         l.sku,
      description: l.description,
      qty,
      unit_price:  unit,
      line_total:  round2(qty * unit),
    };
  });

if (lines.length === 0) {
  throw new Error(`No line items found for ${order.order_id} - cannot invoice an empty order`);
}

const subtotal = round2(lines.reduce((s, l) => s + l.line_total, 0));
const vat      = round2(subtotal * Number(cfg.vatRate));
const total    = round2(subtotal + vat);

// Cross-check against what WF1 registered.
const registered = Number(order.total_incl_vat);
const drift = Number.isFinite(registered) ? round2(total - registered) : null;

return [{
  json: {
    order_id:       order.order_id,
    po_number:      order.po_number,
    order_date:     order.order_date,
    customer_code:  order.customer_code,
    customer_name:  order.customer_name,
    customer_vat:   order.customer_vat,
    customer_email: order.customer_email,
    currency:       order.currency || cfg.currency,

    lines,
    line_count: lines.length,

    subtotal_excl_vat: subtotal,
    vat_amount:        vat,
    total_incl_vat:    total,

    registered_total: Number.isFinite(registered) ? registered : null,
    total_drift:      drift,
    totals_agree:     drift === null ? null : Math.abs(drift) <= 0.05,

    order_row_number: order.row_number,
  },
}];

// 09a · Reserve the invoice number - or reuse one already reserved.
const invoice = $('07 · Build invoice & totals').first().json;
const order   = $('05 · One at a time').first().json;

const rows = $input.all().map((i) => i.json);
const cfg  = (k) => rows.find((r) => String(r.key).trim() === k)?.value;

const prefix = String(cfg('invoice_prefix') ?? 'INV').trim();
const year   = String(cfg('invoice_year') ?? new Date().getFullYear()).trim();

const existing = String(order.invoice_number ?? '').trim();
let invoice_number, next_counter, reused;

if (existing) {
  // A previous run reserved this and failed before producing the PDF.
  invoice_number = existing;
  next_counter   = Number(cfg('invoice_counter') ?? 0);   // unchanged
  reused         = true;
} else {
  const current = Number(cfg('invoice_counter') ?? 0);
  next_counter  = current + 1;
  invoice_number = `${prefix}-${year}-${String(next_counter).padStart(4, '0')}`;
  reused = false;
}

return [{
  json: {
    ...invoice,
    invoice_number,
    next_counter,
    reused_existing_number: reused,
    invoice_date: new Date().toLocaleDateString('en-ZA', {
      timeZone: 'Africa/Johannesburg', year: 'numeric', month: '2-digit', day: '2-digit',
    }),
  },
}];

// 12 · One payload describing every cell to write - header, customer,
// all line items, and the totals - in a single request.
const inv    = $('09a · Reserve invoice number').first().json;
const copyId = $('11 · Copy invoice template').first().json.id;

const money = (n) => Number(n).toFixed(2);

// Line items as a 2D array: one inner array per row.
const lineRows = inv.lines.map((l) => [
  l.sku,
  l.description,
  l.qty,
  money(l.unit_price),
  money(l.line_total),
]);

const lastRow = 11 + lineRows.length;   // items start at row 12

const data = [
  { range: 'Sheet1!D2', values: [[inv.invoice_number]] },
  { range: 'Sheet1!D3', values: [[inv.invoice_date]] },
  { range: 'Sheet1!D4', values: [[inv.po_number || inv.order_id]] },

  { range: 'Sheet1!A7:A9', values: [
      [inv.customer_name],
      [`VAT Reg No: ${inv.customer_vat || '-'}`],
      [inv.customer_email || ''],
  ]},

  { range: `Sheet1!A12:E${lastRow}`, values: lineRows },

  { range: 'Sheet1!D27:D29', values: [
      [money(inv.subtotal_excl_vat)],
      [money(inv.vat_amount)],
      [money(inv.total_incl_vat)],
  ]},
];

return [{
  json: {
    spreadsheetId: copyId,
    invoice_number: inv.invoice_number,
    body: { valueInputOption: 'USER_ENTERED', data },
  },
}];

